-- Guardian 40647 / native scenario 990: real chest loot and final-stage admission.
-- Data only; keeps the original native 199963 scene/equip/credit and NPC handoff.
SET @guardian_concat := @@SESSION.group_concat_max_len;
SET SESSION group_concat_max_len=GREATEST(@@SESSION.group_concat_max_len,1048576);
DROP TEMPORARY TABLE IF EXISTS guardian_pickup_expected;
CREATE TEMPORARY TABLE guardian_pickup_expected LIKE conditions;
INSERT INTO guardian_pickup_expected
(SourceTypeOrReferenceId,SourceGroup,SourceEntry,SourceId,ElseGroup,ConditionTypeOrReference,ConditionTarget,ConditionValue1,ConditionValue2,ConditionValue3,NegativeCondition,ErrorTextId,ScriptName,Comment)
SELECT scope.kind,scope.grp,scope.entry,scope.source,variant.grp,
 IF(rule.kind=0,variant.quest,rule.kind),0,rule.value1,
 IF(rule.kind=44,variant.stage,IF(rule.kind=2,1,0)),
 IF(rule.kind=2 AND scope.kind=4,1,0),IF(rule.kind=2 AND scope.kind=4,1,rule.negative),
 0,'','Guardian: native Claws loot and owned final-stage presentation'
FROM (SELECT 4 kind,248853 grp,128821 entry,0 source
 UNION ALL SELECT 22,1,248853,1 UNION ALL SELECT 22,3,248853,1) scope
CROSS JOIN (SELECT 0 grp,7 stage,9 quest UNION ALL SELECT 1,7,28
 UNION ALL SELECT 2,8,9 UNION ALL SELECT 3,8,28) variant
CROSS JOIN (SELECT 2 kind,128821 value1,0 negative UNION ALL SELECT 15,1024,0
 UNION ALL SELECT 22,1536,0 UNION ALL SELECT 44,990,0 UNION ALL SELECT 0,40647,0
 UNION ALL SELECT 8,40647,1 UNION ALL SELECT 36,0,0) rule
WHERE scope.kind=22 OR variant.stage=7;
START TRANSACTION;
SET @guardian_safe := (SELECT COUNT(*) FROM gameobject_template WHERE entry=248853 AND Data1 IN(0,248853))=1
 AND (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('|',COALESCE(CAST(`entry` AS CHAR),'NULL'),COALESCE(CAST(`type` AS CHAR),'NULL'),COALESCE(CAST(`displayId` AS CHAR),'NULL'),COALESCE(CAST(`name` AS CHAR),'NULL'),COALESCE(CAST(`IconName` AS CHAR),'NULL'),COALESCE(CAST(`castBarCaption` AS CHAR),'NULL'),COALESCE(CAST(`unk1` AS CHAR),'NULL'),COALESCE(CAST(`faction` AS CHAR),'NULL'),COALESCE(CAST(`flags` AS CHAR),'NULL'),COALESCE(CAST(`size` AS CHAR),'NULL'),COALESCE(CAST(`questItem1` AS CHAR),'NULL'),COALESCE(CAST(`questItem2` AS CHAR),'NULL'),COALESCE(CAST(`questItem3` AS CHAR),'NULL'),COALESCE(CAST(`questItem4` AS CHAR),'NULL'),COALESCE(CAST(`questItem5` AS CHAR),'NULL'),COALESCE(CAST(`questItem6` AS CHAR),'NULL'),COALESCE(CAST(`Data0` AS CHAR),'NULL'),'0',COALESCE(CAST(`Data2` AS CHAR),'NULL'),COALESCE(CAST(`Data3` AS CHAR),'NULL'),COALESCE(CAST(`Data4` AS CHAR),'NULL'),COALESCE(CAST(`Data5` AS CHAR),'NULL'),COALESCE(CAST(`Data6` AS CHAR),'NULL'),COALESCE(CAST(`Data7` AS CHAR),'NULL'),COALESCE(CAST(`Data8` AS CHAR),'NULL'),COALESCE(CAST(`Data9` AS CHAR),'NULL'),COALESCE(CAST(`Data10` AS CHAR),'NULL'),COALESCE(CAST(`Data11` AS CHAR),'NULL'),COALESCE(CAST(`Data12` AS CHAR),'NULL'),COALESCE(CAST(`Data13` AS CHAR),'NULL'),COALESCE(CAST(`Data14` AS CHAR),'NULL'),COALESCE(CAST(`Data15` AS CHAR),'NULL'),COALESCE(CAST(`Data16` AS CHAR),'NULL'),COALESCE(CAST(`Data17` AS CHAR),'NULL'),COALESCE(CAST(`Data18` AS CHAR),'NULL'),COALESCE(CAST(`Data19` AS CHAR),'NULL'),COALESCE(CAST(`Data20` AS CHAR),'NULL'),COALESCE(CAST(`Data21` AS CHAR),'NULL'),COALESCE(CAST(`Data22` AS CHAR),'NULL'),COALESCE(CAST(`Data23` AS CHAR),'NULL'),COALESCE(CAST(`Data24` AS CHAR),'NULL'),COALESCE(CAST(`Data25` AS CHAR),'NULL'),COALESCE(CAST(`Data26` AS CHAR),'NULL'),COALESCE(CAST(`Data27` AS CHAR),'NULL'),COALESCE(CAST(`Data28` AS CHAR),'NULL'),COALESCE(CAST(`Data29` AS CHAR),'NULL'),COALESCE(CAST(`Data30` AS CHAR),'NULL'),COALESCE(CAST(`Data31` AS CHAR),'NULL'),COALESCE(CAST(`Data32` AS CHAR),'NULL'),COALESCE(CAST(`unkInt32` AS CHAR),'NULL'),COALESCE(CAST(`AIName` AS CHAR),'NULL'),COALESCE(CAST(`ScriptName` AS CHAR),'NULL'),COALESCE(CAST(`WorldEffectID` AS CHAR),'NULL'),COALESCE(CAST(`StateWorldEffectID` AS CHAR),'NULL'),COALESCE(CAST(`SpellVisualID` AS CHAR),'NULL'),COALESCE(CAST(`SpellStateVisualID` AS CHAR),'NULL'),COALESCE(CAST(`SpellStateAnimID` AS CHAR),'NULL'),COALESCE(CAST(`SpellStateAnimKitID` AS CHAR),'NULL'),COALESCE(CAST(`MaxVisible` AS CHAR),'NULL'),COALESCE(CAST(`IgnoreDynLos` AS CHAR),'NULL'),COALESCE(CAST(`MinGold` AS CHAR),'NULL'),COALESCE(CAST(`MaxGold` AS CHAR),'NULL'),COALESCE(CAST(`VerifiedBuild` AS CHAR),'NULL')) ORDER BY `entry`,`type`,`displayId`,`name`,`IconName`,`castBarCaption`,`unk1`,`faction`,`flags`,`size`,`questItem1`,`questItem2`,`questItem3`,`questItem4`,`questItem5`,`questItem6`,`Data0`,`Data1`,`Data2`,`Data3`,`Data4`,`Data5`,`Data6`,`Data7`,`Data8`,`Data9`,`Data10`,`Data11`,`Data12`,`Data13`,`Data14`,`Data15`,`Data16`,`Data17`,`Data18`,`Data19`,`Data20`,`Data21`,`Data22`,`Data23`,`Data24`,`Data25`,`Data26`,`Data27`,`Data28`,`Data29`,`Data30`,`Data31`,`Data32`,`unkInt32`,`AIName`,`ScriptName`,`WorldEffectID`,`StateWorldEffectID`,`SpellVisualID`,`SpellStateVisualID`,`SpellStateAnimID`,`SpellStateAnimKitID`,`MaxVisible`,`IgnoreDynLos`,`MinGold`,`MaxGold`,`VerifiedBuild` SEPARATOR '\n'),256) FROM gameobject_template WHERE entry=248853)='e0d11eb6cc39c2d0a7f74d0942412a21460ec546fa09f6ee51e0417ab975dac9'
 AND (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('|',COALESCE(CAST(`Entry` AS CHAR),'NULL'),COALESCE(CAST(`Item` AS CHAR),'NULL'),COALESCE(CAST(`Currency` AS CHAR),'NULL'),COALESCE(CAST(`Reference` AS CHAR),'NULL'),COALESCE(CAST(`Chance` AS CHAR),'NULL'),COALESCE(CAST(`QuestRequired` AS CHAR),'NULL'),COALESCE(CAST(`LootMode` AS CHAR),'NULL'),COALESCE(CAST(`GroupId` AS CHAR),'NULL'),COALESCE(CAST(`MinCount` AS CHAR),'NULL'),COALESCE(CAST(`MaxCount` AS CHAR),'NULL'),COALESCE(CAST(`Comment` AS CHAR),'NULL')) ORDER BY `Entry`,`Item`,`Currency`,`Reference`,`Chance`,`QuestRequired`,`LootMode`,`GroupId`,`MinCount`,`MaxCount`,`Comment` SEPARATOR '\n'),256) FROM gameobject_loot_template WHERE Entry=248853)='0acf5ee92cd225d7b463d1d36190cb3df8e620849e5ad0e1ed2140110aa33ef9'
 AND (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('|',COALESCE(CAST(`entryorguid` AS CHAR),'NULL'),COALESCE(CAST(`source_type` AS CHAR),'NULL'),COALESCE(CAST(`id` AS CHAR),'NULL'),COALESCE(CAST(`link` AS CHAR),'NULL'),COALESCE(CAST(`Difficulties` AS CHAR),'NULL'),COALESCE(CAST(`event_type` AS CHAR),'NULL'),COALESCE(CAST(`event_phase_mask` AS CHAR),'NULL'),COALESCE(CAST(`event_chance` AS CHAR),'NULL'),COALESCE(CAST(`event_flags` AS CHAR),'NULL'),COALESCE(CAST(`event_param1` AS CHAR),'NULL'),COALESCE(CAST(`event_param2` AS CHAR),'NULL'),COALESCE(CAST(`event_param3` AS CHAR),'NULL'),COALESCE(CAST(`event_param4` AS CHAR),'NULL'),COALESCE(CAST(`event_param5` AS CHAR),'NULL'),COALESCE(CAST(`action_type` AS CHAR),'NULL'),COALESCE(CAST(`action_param1` AS CHAR),'NULL'),COALESCE(CAST(`action_param2` AS CHAR),'NULL'),COALESCE(CAST(`action_param3` AS CHAR),'NULL'),COALESCE(CAST(`action_param4` AS CHAR),'NULL'),COALESCE(CAST(`action_param5` AS CHAR),'NULL'),COALESCE(CAST(`action_param6` AS CHAR),'NULL'),COALESCE(CAST(`target_type` AS CHAR),'NULL'),COALESCE(CAST(`target_param1` AS CHAR),'NULL'),COALESCE(CAST(`target_param2` AS CHAR),'NULL'),COALESCE(CAST(`target_param3` AS CHAR),'NULL'),COALESCE(CAST(`target_param4` AS CHAR),'NULL'),COALESCE(CAST(`target_x` AS CHAR),'NULL'),COALESCE(CAST(`target_y` AS CHAR),'NULL'),COALESCE(CAST(`target_z` AS CHAR),'NULL'),COALESCE(CAST(`target_o` AS CHAR),'NULL'),COALESCE(CAST(`comment` AS CHAR),'NULL')) ORDER BY `entryorguid`,`source_type`,`id`,`link`,`Difficulties`,`event_type`,`event_phase_mask`,`event_chance`,`event_flags`,`event_param1`,`event_param2`,`event_param3`,`event_param4`,`event_param5`,`action_type`,`action_param1`,`action_param2`,`action_param3`,`action_param4`,`action_param5`,`action_param6`,`target_type`,`target_param1`,`target_param2`,`target_param3`,`target_param4`,`target_x`,`target_y`,`target_z`,`target_o`,`comment` SEPARATOR '\n'),256) FROM smart_scripts WHERE entryorguid=248853 AND source_type=1)='ab49a114d489268b2b9dd7cca25cb4bcb38de565829ceb7c8d057a1b9572c6ec'
 AND ((SELECT SHA2(GROUP_CONCAT(CONCAT_WS('|',COALESCE(CAST(`SourceTypeOrReferenceId` AS CHAR),'NULL'),COALESCE(CAST(`SourceGroup` AS CHAR),'NULL'),COALESCE(CAST(`SourceEntry` AS CHAR),'NULL'),COALESCE(CAST(`SourceId` AS CHAR),'NULL'),COALESCE(CAST(`ElseGroup` AS CHAR),'NULL'),COALESCE(CAST(`ConditionTypeOrReference` AS CHAR),'NULL'),COALESCE(CAST(`ConditionTarget` AS CHAR),'NULL'),COALESCE(CAST(`ConditionValue1` AS CHAR),'NULL'),COALESCE(CAST(`ConditionValue2` AS CHAR),'NULL'),COALESCE(CAST(`ConditionValue3` AS CHAR),'NULL'),COALESCE(CAST(`NegativeCondition` AS CHAR),'NULL'),COALESCE(CAST(`ErrorTextId` AS CHAR),'NULL'),COALESCE(CAST(`ScriptName` AS CHAR),'NULL'),COALESCE(CAST(`Comment` AS CHAR),'NULL')) ORDER BY `SourceTypeOrReferenceId`,`SourceGroup`,`SourceEntry`,`SourceId`,`ElseGroup`,`ConditionTypeOrReference`,`ConditionTarget`,`ConditionValue1`,`ConditionValue2`,`ConditionValue3`,`NegativeCondition`,`ErrorTextId`,`ScriptName`,`Comment` SEPARATOR '\n'),256) FROM conditions WHERE (SourceTypeOrReferenceId=4 AND SourceGroup=248853) OR (SourceTypeOrReferenceId=22 AND SourceEntry=248853 AND SourceId=1))='6a2c8c2404f13428c8a9d4ff11680f43b749405fa6e35c6aabc0a3c2c8828dd6'
 OR (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('|',COALESCE(CAST(`SourceTypeOrReferenceId` AS CHAR),'NULL'),COALESCE(CAST(`SourceGroup` AS CHAR),'NULL'),COALESCE(CAST(`SourceEntry` AS CHAR),'NULL'),COALESCE(CAST(`SourceId` AS CHAR),'NULL'),COALESCE(CAST(`ElseGroup` AS CHAR),'NULL'),COALESCE(CAST(`ConditionTypeOrReference` AS CHAR),'NULL'),COALESCE(CAST(`ConditionTarget` AS CHAR),'NULL'),COALESCE(CAST(`ConditionValue1` AS CHAR),'NULL'),COALESCE(CAST(`ConditionValue2` AS CHAR),'NULL'),COALESCE(CAST(`ConditionValue3` AS CHAR),'NULL'),COALESCE(CAST(`NegativeCondition` AS CHAR),'NULL'),COALESCE(CAST(`ErrorTextId` AS CHAR),'NULL'),COALESCE(CAST(`ScriptName` AS CHAR),'NULL'),COALESCE(CAST(`Comment` AS CHAR),'NULL')) ORDER BY `SourceTypeOrReferenceId`,`SourceGroup`,`SourceEntry`,`SourceId`,`ElseGroup`,`ConditionTypeOrReference`,`ConditionTarget`,`ConditionValue1`,`ConditionValue2`,`ConditionValue3`,`NegativeCondition`,`ErrorTextId`,`ScriptName`,`Comment` SEPARATOR '\n'),256) FROM conditions WHERE (SourceTypeOrReferenceId=4 AND SourceGroup=248853) OR (SourceTypeOrReferenceId=22 AND SourceEntry=248853 AND SourceId=1))=(SELECT SHA2(GROUP_CONCAT(CONCAT_WS('|',COALESCE(CAST(`SourceTypeOrReferenceId` AS CHAR),'NULL'),COALESCE(CAST(`SourceGroup` AS CHAR),'NULL'),COALESCE(CAST(`SourceEntry` AS CHAR),'NULL'),COALESCE(CAST(`SourceId` AS CHAR),'NULL'),COALESCE(CAST(`ElseGroup` AS CHAR),'NULL'),COALESCE(CAST(`ConditionTypeOrReference` AS CHAR),'NULL'),COALESCE(CAST(`ConditionTarget` AS CHAR),'NULL'),COALESCE(CAST(`ConditionValue1` AS CHAR),'NULL'),COALESCE(CAST(`ConditionValue2` AS CHAR),'NULL'),COALESCE(CAST(`ConditionValue3` AS CHAR),'NULL'),COALESCE(CAST(`NegativeCondition` AS CHAR),'NULL'),COALESCE(CAST(`ErrorTextId` AS CHAR),'NULL'),COALESCE(CAST(`ScriptName` AS CHAR),'NULL'),COALESCE(CAST(`Comment` AS CHAR),'NULL')) ORDER BY `SourceTypeOrReferenceId`,`SourceGroup`,`SourceEntry`,`SourceId`,`ElseGroup`,`ConditionTypeOrReference`,`ConditionTarget`,`ConditionValue1`,`ConditionValue2`,`ConditionValue3`,`NegativeCondition`,`ErrorTextId`,`ScriptName`,`Comment` SEPARATOR '\n'),256) FROM guardian_pickup_expected WHERE 1));
SET @guardian_check := IF(COALESCE(@guardian_safe,0),'DO 0','SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT=''Guardian native chest/loot/actions/conditions differ; review before applying''');
PREPARE guardian_check FROM @guardian_check;EXECUTE guardian_check;DEALLOCATE PREPARE guardian_check;
UPDATE gameobject_template SET Data1=248853 WHERE @guardian_safe AND entry=248853;
DELETE FROM conditions WHERE @guardian_safe AND ((SourceTypeOrReferenceId=4 AND SourceGroup=248853) OR (SourceTypeOrReferenceId=22 AND SourceEntry=248853 AND SourceId=1));
INSERT INTO conditions SELECT * FROM guardian_pickup_expected WHERE @guardian_safe;
COMMIT;
DROP TEMPORARY TABLE guardian_pickup_expected;
SET SESSION group_concat_max_len=@guardian_concat;

